// Author: Andres Ortiz
// Title: Ordered dithering workshop

/*
    *This is how to implement dithering using a random value

    *Get the luminance (brightness) of each pixel

    *Compare it to a random value between 0-1

    *If that pixel's luminance is brighter than the threshold value, 
     the pixel is white, else the pixel becomes black

    *Comes out suprisingly good looking!
*/


float getLum(vec3 color);
float rand(vec2 co);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Sample the texture in channel 0
    vec3 col = texture(iChannel0, uv).rgb;
    // Output to screen
    float lum = getLum(col);

    //implement random value here!
    float threshold = 0.5;

    fragColor.rgb = vec3(1.0 - step(lum, threshold));
}

float getLum(vec3 color){
    return dot(vec3(0.2126, 0.7152, 0.0722), color);
}

float rand(vec2 co)
{
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}
